Item.method_code:
const state = options.getState();
const rowId = state.grid.selectedRows[0];
const { itemTypeName } = options;
const item = options.rows.get(rowId);

const copyItemCommand = options.commandFactory('CopyItem', { item });
let copiedItem = await copyItemCommand.execute();
if (!copiedItem) {
	return;
}

const itemId = copiedItem.getAttribute('id');
aras.fireEvent('ItemSave', {
	itemID: itemId,
	itemNd: copiedItem
});
window.grid.selection_Experimental.clear();
window.onSelectItem(itemId);

if (itemTypeName === 'File') {
	return;
}
if (!aras.getItemProperty(copiedItem, 'locked_by_id')) {
	copiedItem = aras.lockItemEx(copiedItem);
	if (!copiedItem) {
		return;
	}
}

aras.uiShowItemEx(
	copiedItem,
	aras.getPreferenceItemProperty(
		'Core_GlobalLayout',
		null,
		'core_view_mode'
	)
);
